import{_ as i,o as e,c as t,ag as l}from"./chunks/framework.rAhUSuuf.js";const u=JSON.parse('{"title":"运行时配置中心设计（以限流热更新为首个落地）","description":"","frontmatter":{},"headers":[],"relativePath":"design/runtime-config-center.md","filePath":"design/runtime-config-center.md","lastUpdated":1771040072000}'),o={name:"design/runtime-config-center.md"};function s(d,a,n,r,h,c){return e(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="运行时配置中心设计-以限流热更新为首个落地" tabindex="-1">运行时配置中心设计（以限流热更新为首个落地） <a class="header-anchor" href="#运行时配置中心设计-以限流热更新为首个落地" aria-label="Permalink to &quot;运行时配置中心设计（以限流热更新为首个落地）&quot;">​</a></h1><h2 id="背景与目标" tabindex="-1">背景与目标 <a class="header-anchor" href="#背景与目标" aria-label="Permalink to &quot;背景与目标&quot;">​</a></h2><p>在实际运维中，后端经常需要在<strong>不中断服务</strong>的前提下调整系统行为，例如：</p><ul><li>临时放宽限流阈值应对突发流量</li><li>在批量导入期间关闭限流</li><li>逐步收紧风控参数进行灰度</li></ul><p>此前全局限流逻辑在 <code>AppModule</code> 中被注释，虽然能解决临时导入问题，但带来两个风险：</p><ol><li>安全防护“整体失效”</li><li>需要改代码 + 重启服务才能恢复</li></ol><p>因此我们引入独立的 <strong>Runtime Config Center（运行时配置中心）</strong>，第一阶段只承载 <code>rate_limit</code> 配置，并确保后续可以平滑扩展更多系统级动态配置。</p><h2 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h2><h3 id="职责分离" tabindex="-1">职责分离 <a class="header-anchor" href="#职责分离" aria-label="Permalink to &quot;职责分离&quot;">​</a></h3><ul><li><code>SettingsModule</code>：面向用户/工作空间偏好（产品体验层）</li><li><code>RuntimeConfigModule</code>：面向系统运行参数（运维控制层）</li></ul><p>两者隔离，避免把“用户偏好设置”与“系统控制开关”混在同一语义域中。</p><h3 id="热更新优先" tabindex="-1">热更新优先 <a class="header-anchor" href="#热更新优先" aria-label="Permalink to &quot;热更新优先&quot;">​</a></h3><p>配置修改后：</p><ul><li>当前实例立即生效</li><li>其他实例通过短轮询快速同步（默认 5 秒）</li></ul><h3 id="安全最小暴露" tabindex="-1">安全最小暴露 <a class="header-anchor" href="#安全最小暴露" aria-label="Permalink to &quot;安全最小暴露&quot;">​</a></h3><p>运行时配置接口使用独立令牌：<code>x-system-admin-token</code></p><p>不复用普通 JWT 用户权限，降低误用风险。</p><h3 id="扩展优先" tabindex="-1">扩展优先 <a class="header-anchor" href="#扩展优先" aria-label="Permalink to &quot;扩展优先&quot;">​</a></h3><p>第一阶段只实现 <code>rate_limit</code>，但模型、模块、API 结构按“多配置键”设计。</p><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  RuntimeConfigModule               │</span></span>
<span class="line"><span>│                                                    │</span></span>
<span class="line"><span>│  ┌────────────────────┐   ┌─────────────────────┐  │</span></span>
<span class="line"><span>│  │ RuntimeConfigCtrl  │──▶│ RuntimeConfigService│──┼─▶ DB(runtime_configs)</span></span>
<span class="line"><span>│  └────────────────────┘   └─────────────────────┘  │</span></span>
<span class="line"><span>│                                 ▲                  │</span></span>
<span class="line"><span>└─────────────────────────────────┼──────────────────┘</span></span>
<span class="line"><span>                                  │</span></span>
<span class="line"><span>                                  │（每请求读取缓存快照）</span></span>
<span class="line"><span>                       ┌──────────────────────────────┐</span></span>
<span class="line"><span>                       │ ThrottlerModule + Guard      │</span></span>
<span class="line"><span>                       │ ttl/limit/skipIf 动态函数    │</span></span>
<span class="line"><span>                       └──────────────────────────────┘</span></span></code></pre></div><h2 id="数据模型设计" tabindex="-1">数据模型设计 <a class="header-anchor" href="#数据模型设计" aria-label="Permalink to &quot;数据模型设计&quot;">​</a></h2><h2 id="表结构-runtime-configs" tabindex="-1">表结构：<code>runtime_configs</code> <a class="header-anchor" href="#表结构-runtime-configs" aria-label="Permalink to &quot;表结构：\`runtime_configs\`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>bigserial</code></td><td>主键</td></tr><tr><td><code>config_key</code></td><td><code>varchar(100)</code></td><td>配置键（唯一），例如 <code>rate_limit</code></td></tr><tr><td><code>config_value</code></td><td><code>jsonb</code></td><td>配置值（结构化 JSON）</td></tr><tr><td><code>updated_by</code></td><td><code>varchar(64)</code></td><td>最近修改人（可来自 <code>x-operator-id</code>）</td></tr><tr><td><code>created_at</code></td><td><code>timestamptz</code></td><td>创建时间</td></tr><tr><td><code>updated_at</code></td><td><code>timestamptz</code></td><td>更新时间</td></tr></tbody></table><p>唯一索引：<code>IDX_runtime_configs_config_key</code></p><h3 id="为什么使用-jsonb" tabindex="-1">为什么使用 <code>jsonb</code> <a class="header-anchor" href="#为什么使用-jsonb" aria-label="Permalink to &quot;为什么使用 \`jsonb\`&quot;">​</a></h3><ol><li>支持不同配置键的异构结构</li><li>后续新增配置无需频繁改表</li><li>与 TypeORM + PostgreSQL 配合成熟</li></ol><h2 id="关键模块与代码职责" tabindex="-1">关键模块与代码职责 <a class="header-anchor" href="#关键模块与代码职责" aria-label="Permalink to &quot;关键模块与代码职责&quot;">​</a></h2><h2 id="runtimeconfigservice" tabindex="-1"><code>RuntimeConfigService</code> <a class="header-anchor" href="#runtimeconfigservice" aria-label="Permalink to &quot;\`RuntimeConfigService\`&quot;">​</a></h2><p>核心职责：</p><ol><li>启动时加载 DB 配置到内存缓存</li><li>不存在时写入默认配置（bootstrap）</li><li>提供限流配置读写能力</li><li>提供短轮询跨实例同步</li><li>给 <code>ThrottlerModule</code> 提供低开销快照读取接口</li></ol><p>核心接口（语义）：</p><ul><li><code>getRateLimitConfigSnapshot()</code>：同步读缓存（供 Guard 高频调用）</li><li><code>getRateLimitConfig()</code>：强一致读取（先轮询刷新，再返回）</li><li><code>updateRateLimitConfig()</code>：合并补丁 + 落库 + 刷新缓存</li><li><code>resetRateLimitConfig()</code>：回到 env 默认值</li></ul><h2 id="systemadmintokenguard" tabindex="-1"><code>SystemAdminTokenGuard</code> <a class="header-anchor" href="#systemadmintokenguard" aria-label="Permalink to &quot;\`SystemAdminTokenGuard\`&quot;">​</a></h2><p>职责：</p><ul><li>校验 <code>x-system-admin-token</code></li><li>拒绝未配置或错误令牌请求（403）</li></ul><h2 id="runtimeconfigcontroller" tabindex="-1"><code>RuntimeConfigController</code> <a class="header-anchor" href="#runtimeconfigcontroller" aria-label="Permalink to &quot;\`RuntimeConfigController\`&quot;">​</a></h2><p>职责：</p><ul><li>暴露运行时配置 API（读取、更新、重置）</li><li>统一从 <code>x-operator-id</code> 或 IP 推导操作者标识</li></ul><h2 id="appmodule-中限流恢复方式" tabindex="-1"><code>AppModule</code> 中限流恢复方式 <a class="header-anchor" href="#appmodule-中限流恢复方式" aria-label="Permalink to &quot;\`AppModule\` 中限流恢复方式&quot;">​</a></h2><p>通过 <code>ThrottlerModule.forRootAsync</code> 动态读取配置：</p><ul><li><code>ttl</code> -&gt; <code>runtimeConfigService.getRateLimitConfigForGuard().ttlMs</code></li><li><code>limit</code> -&gt; <code>...limit</code></li><li><code>skipIf</code> -&gt; <code>!enabled</code></li></ul><p>这使得“是否限流 + 限流参数”都可在线调整。</p><h2 id="生命周期与数据流" tabindex="-1">生命周期与数据流 <a class="header-anchor" href="#生命周期与数据流" aria-label="Permalink to &quot;生命周期与数据流&quot;">​</a></h2><h2 id="启动流程" tabindex="-1">启动流程 <a class="header-anchor" href="#启动流程" aria-label="Permalink to &quot;启动流程&quot;">​</a></h2><ol><li>Nest 启动 <code>RuntimeConfigModule</code></li><li><code>RuntimeConfigService.onModuleInit()</code></li><li>从 <code>runtime_configs</code> 读取所有配置到内存</li><li>若缺少 <code>rate_limit</code>，写入默认值（来自环境变量）</li><li>启动轮询任务（<code>RUNTIME_CONFIG_POLL_INTERVAL_MS</code>）</li></ol><h2 id="请求限流判定流程" tabindex="-1">请求限流判定流程 <a class="header-anchor" href="#请求限流判定流程" aria-label="Permalink to &quot;请求限流判定流程&quot;">​</a></h2><ol><li>请求进入 <code>ThrottlerGuard</code></li><li>Guard 调用配置函数获取 <code>enabled/ttlMs/limit</code></li><li><code>enabled=false</code> 时直接跳过</li><li><code>enabled=true</code> 时按当前参数执行限流</li></ol><h2 id="配置更新流程" tabindex="-1">配置更新流程 <a class="header-anchor" href="#配置更新流程" aria-label="Permalink to &quot;配置更新流程&quot;">​</a></h2><ol><li>管理请求进入 <code>RuntimeConfigController</code></li><li><code>SystemAdminTokenGuard</code> 校验通过</li><li>DTO 参数校验</li><li>Service 合并当前值 + patch，做边界收敛</li><li>落库（upsert）并更新本实例缓存</li><li>其他实例在轮询窗口内同步</li></ol><h2 id="一致性策略与多实例行为" tabindex="-1">一致性策略与多实例行为 <a class="header-anchor" href="#一致性策略与多实例行为" aria-label="Permalink to &quot;一致性策略与多实例行为&quot;">​</a></h2><p>本阶段采用“<strong>最终一致 + 快速收敛</strong>”：</p><ul><li>写入实例：立即生效（本地缓存即时更新）</li><li>其他实例：轮询读取 DB（默认 5 秒）</li></ul><h3 id="优势" tabindex="-1">优势 <a class="header-anchor" href="#优势" aria-label="Permalink to &quot;优势&quot;">​</a></h3><ul><li>实现简单</li><li>对现有架构侵入小</li><li>无需额外中间件（如 Redis Pub/Sub）</li></ul><h3 id="代价" tabindex="-1">代价 <a class="header-anchor" href="#代价" aria-label="Permalink to &quot;代价&quot;">​</a></h3><ul><li>多实例下存在秒级传播延迟</li></ul><h3 id="后续可升级方案" tabindex="-1">后续可升级方案 <a class="header-anchor" href="#后续可升级方案" aria-label="Permalink to &quot;后续可升级方案&quot;">​</a></h3><ul><li>方案 A：Redis Pub/Sub 事件通知（低延迟）</li><li>方案 B：CDC + 消费总线</li><li>方案 C：管理接口写库后主动广播刷新</li></ul><h2 id="配置校验与边界收敛" tabindex="-1">配置校验与边界收敛 <a class="header-anchor" href="#配置校验与边界收敛" aria-label="Permalink to &quot;配置校验与边界收敛&quot;">​</a></h2><p>限流配置约束：</p><ul><li><code>ttlMs</code>: <code>1000 ~ 86400000</code></li><li><code>limit</code>: <code>1 ~ 100000</code></li><li><code>enabled</code>: boolean</li></ul><p>策略：</p><ul><li>API 入参先走 <code>class-validator</code></li><li>Service 内部再做归一化兜底（防止脏数据进入）</li></ul><p>这样即使有人绕过 API 直接写 DB，服务侧也能最大限度自恢复。</p><h2 id="错误处理设计" tabindex="-1">错误处理设计 <a class="header-anchor" href="#错误处理设计" aria-label="Permalink to &quot;错误处理设计&quot;">​</a></h2><p>在全局异常过滤器中，对 HTTP <code>429</code> 统一映射：</p><p><code>code = RATE_6001</code>（<code>ErrorCode.RATE_LIMIT_EXCEEDED</code>）</p><p>目标：</p><ol><li>前端可稳定识别限流错误码</li><li>降低 <code>ThrottlerException</code> 原始文本差异带来的兼容问题</li></ol><h2 id="安全设计细节" tabindex="-1">安全设计细节 <a class="header-anchor" href="#安全设计细节" aria-label="Permalink to &quot;安全设计细节&quot;">​</a></h2><h2 id="为什么不用-jwt-权限体系" tabindex="-1">为什么不用 JWT 权限体系 <a class="header-anchor" href="#为什么不用-jwt-权限体系" aria-label="Permalink to &quot;为什么不用 JWT 权限体系&quot;">​</a></h2><p>JWT 体系主要表达“用户业务权限”，而运行时配置是“系统运维权限”，边界不同。</p><p>若复用 JWT，可能出现：</p><ul><li>某个管理员账号被盗导致系统参数被恶意修改</li><li>业务权限模型复杂化（workspace admin 与系统 admin 混淆）</li></ul><p>独立令牌机制可把权限平面隔离：</p><ul><li>应用层用户权限（JWT）</li><li>运维层系统权限（SYSTEM_ADMIN_TOKEN）</li></ul><h2 id="推荐生产实践" tabindex="-1">推荐生产实践 <a class="header-anchor" href="#推荐生产实践" aria-label="Permalink to &quot;推荐生产实践&quot;">​</a></h2><ol><li><code>SYSTEM_ADMIN_TOKEN</code> 使用高熵随机串（&gt;= 32 字符）</li><li>通过密钥平台注入，不写入代码库</li><li>反向代理层限制来源网段</li><li>结合 WAF/堡垒机控制访问入口</li><li>配置修改动作接入审计（可在后续版本补齐独立审计表）</li></ol><h2 id="api-使用手册-运维视角" tabindex="-1">API 使用手册（运维视角） <a class="header-anchor" href="#api-使用手册-运维视角" aria-label="Permalink to &quot;API 使用手册（运维视角）&quot;">​</a></h2><h2 id="读取当前配置" tabindex="-1">读取当前配置 <a class="header-anchor" href="#读取当前配置" aria-label="Permalink to &quot;读取当前配置&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:5200/api/v1/runtime-configs/rate-limit&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-system-admin-token: &lt;SYSTEM_ADMIN_TOKEN&gt;&quot;</span></span></code></pre></div><h2 id="批量导入前关闭限流" tabindex="-1">批量导入前关闭限流 <a class="header-anchor" href="#批量导入前关闭限流" aria-label="Permalink to &quot;批量导入前关闭限流&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:5200/api/v1/runtime-configs/rate-limit&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-system-admin-token: &lt;SYSTEM_ADMIN_TOKEN&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-operator-id: import_pipeline&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;enabled&quot;: false}&#39;</span></span></code></pre></div><h2 id="导入后恢复限流" tabindex="-1">导入后恢复限流 <a class="header-anchor" href="#导入后恢复限流" aria-label="Permalink to &quot;导入后恢复限流&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:5200/api/v1/runtime-configs/rate-limit&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-system-admin-token: &lt;SYSTEM_ADMIN_TOKEN&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;enabled&quot;: true, &quot;ttlMs&quot;: 60000, &quot;limit&quot;: 100}&#39;</span></span></code></pre></div><h2 id="一键重置默认值" tabindex="-1">一键重置默认值 <a class="header-anchor" href="#一键重置默认值" aria-label="Permalink to &quot;一键重置默认值&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:5200/api/v1/runtime-configs/rate-limit/reset&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;x-system-admin-token: &lt;SYSTEM_ADMIN_TOKEN&gt;&quot;</span></span></code></pre></div><h2 id="环境变量说明" tabindex="-1">环境变量说明 <a class="header-anchor" href="#环境变量说明" aria-label="Permalink to &quot;环境变量说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>RATE_LIMIT_ENABLED</code></td><td><code>true</code></td><td>默认是否启用限流</td></tr><tr><td><code>RATE_LIMIT_TTL</code></td><td><code>60000</code></td><td>默认时间窗口（毫秒）</td></tr><tr><td><code>RATE_LIMIT_MAX</code></td><td><code>100</code></td><td>默认窗口内请求上限</td></tr><tr><td><code>RUNTIME_CONFIG_POLL_INTERVAL_MS</code></td><td><code>5000</code></td><td>多实例同步轮询间隔</td></tr><tr><td><code>SYSTEM_ADMIN_TOKEN</code></td><td>空</td><td>运行时配置管理令牌</td></tr><tr><td><code>PUBLIC_SITE_ORIGINS</code></td><td>空</td><td>publish 站点白名单；支持精确 origin、<code>*</code>、<code>https://*.example.com</code>；当前仍为静态环境变量，不纳入 runtime center</td></tr><tr><td><code>PUBLIC_SITE_ALLOW_NO_ORIGIN</code></td><td><code>false</code></td><td>是否允许无 <code>Origin</code> / <code>Referer</code> 的匿名请求访问 <code>@SitePublic()</code> 接口</td></tr></tbody></table><blockquote><p>说明：<code>PUBLIC_SITE_ORIGINS</code> 目前只在应用启动时读取，用于 <code>@SitePublic()</code> 请求来源校验和 CORS 白名单合并；后续如需在线调整，再纳入运行时配置中心。</p><p><code>PUBLIC_SITE_ALLOW_NO_ORIGIN</code> 也仅在启动时读取，且只影响 <code>@SitePublic()</code> 接口的匿名访问判定。</p></blockquote><h2 id="兼容性与回滚策略" tabindex="-1">兼容性与回滚策略 <a class="header-anchor" href="#兼容性与回滚策略" aria-label="Permalink to &quot;兼容性与回滚策略&quot;">​</a></h2><h2 id="与历史行为兼容" tabindex="-1">与历史行为兼容 <a class="header-anchor" href="#与历史行为兼容" aria-label="Permalink to &quot;与历史行为兼容&quot;">​</a></h2><ul><li>旧行为：限流在代码里写死/注释</li><li>新行为：限流始终启用框架能力，配置由 runtime center 控制</li></ul><p>对业务方来说，接口保持不变，差异只体现在限流是否生效和阈值变化。</p><h2 id="回滚策略" tabindex="-1">回滚策略 <a class="header-anchor" href="#回滚策略" aria-label="Permalink to &quot;回滚策略&quot;">​</a></h2><p>如需紧急回滚：</p><ol><li>先用 API 将 <code>enabled=false</code>（立即止损）</li><li>回退服务版本</li><li>保留 <code>runtime_configs</code> 数据（不影响旧版本）</li></ol><h2 id="可观测性建议" tabindex="-1">可观测性建议 <a class="header-anchor" href="#可观测性建议" aria-label="Permalink to &quot;可观测性建议&quot;">​</a></h2><p>建议在后续迭代新增：</p><ol><li>配置变更审计日志（谁在何时改了什么）</li><li>配置版本号（用于快速对比）</li><li><code>/runtime-configs/health</code> 用于巡检缓存与 DB 一致性</li><li>指标埋点（配置读取命中率、轮询耗时、同步延迟）</li></ol><h2 id="演进路线-roadmap" tabindex="-1">演进路线（Roadmap） <a class="header-anchor" href="#演进路线-roadmap" aria-label="Permalink to &quot;演进路线（Roadmap）&quot;">​</a></h2><p>第二阶段可纳入以下配置键：</p><ul><li><code>upload_limits</code>：上传大小、类型、并发控制</li><li><code>auth_policy</code>：登录失败锁定策略、token 续签策略</li><li><code>search_limits</code>：搜索分页上限、并发查询阈值</li><li><code>feature_switches</code>：高风险功能开关</li></ul><p>演进建议：</p><ol><li>引入配置注册表（schema + 默认值 + 校验器）</li><li>抽象通用 CRUD + 版本管理</li><li>增加批量更新与事务语义</li><li>提供变更订阅能力（事件总线）</li></ol><h2 id="测试建议清单" tabindex="-1">测试建议清单 <a class="header-anchor" href="#测试建议清单" aria-label="Permalink to &quot;测试建议清单&quot;">​</a></h2><h2 id="单元测试" tabindex="-1">单元测试 <a class="header-anchor" href="#单元测试" aria-label="Permalink to &quot;单元测试&quot;">​</a></h2><ul><li><code>normalizeRateLimitRuntimeConfig</code> 边界值测试</li><li><code>SystemAdminTokenGuard</code> 的通过/拒绝路径</li><li>reset 逻辑回退到 env 默认值</li></ul><h2 id="集成测试" tabindex="-1">集成测试 <a class="header-anchor" href="#集成测试" aria-label="Permalink to &quot;集成测试&quot;">​</a></h2><ul><li>更新配置后，同实例限流行为立即变化</li><li>错误令牌访问返回 403</li><li>限流触发时返回 429 + <code>RATE_6001</code></li></ul><h2 id="多实例测试" tabindex="-1">多实例测试 <a class="header-anchor" href="#多实例测试" aria-label="Permalink to &quot;多实例测试&quot;">​</a></h2><ul><li>A 实例修改后 B 在轮询窗口内生效</li><li>网络抖动场景下轮询失败可自恢复</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次改造把“注释代码临时开关”升级为“正式运行时配置能力”，实现了：</p><ol><li>限流能力恢复</li><li>在线可控（无需重启）</li><li>多实例可同步</li><li>权限边界清晰</li><li>为后续更多动态配置提供统一基础设施</li></ol>`,116)])])}const k=i(o,[["render",s]]);export{u as __pageData,k as default};
